package org.springframework.samples.petclinic.owner.blackbox;

import static org.springframework.samples.petclinic.owner.blackbox.support.BlackBoxSupport.BASE_URL;
import static org.springframework.samples.petclinic.owner.blackbox.support.BlackBoxSupport.executeSqlTemplate;
import static org.springframework.samples.petclinic.owner.blackbox.support.BlackBoxSupport.queryScalar;
import static org.springframework.samples.petclinic.owner.blackbox.support.BlackBoxSupport.testId;
import static org.springframework.samples.petclinic.owner.blackbox.support.BlackBoxSupport.testSeq;
import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.containsString;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.notNullValue;

import java.util.Map;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import io.restassured.http.ContentType;

/**
 * Black-Box API Integration Test (template-rendered v2)
 *
 * @target-controller OwnerRestController (src/main/java/org/springframework/samples/petclinic/owner/OwnerRestController.java)
 * @target-api GET /api/owners/{ownerId}
 *
 * Retrieves a specific owner by their ID
 * Authorization: Bearer token required
 * Returns 200 OK with owner data if found, 404 if not found
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class GetOwnerByIdBlackBoxTest {

    private Map<String, String> seed(TestInfo info) {
        long seq = testSeq(info);
        return Map.of(
                "SEQ", Long.toString(seq),
                "ID", "owner" + testId(info));
    }

    private void arrange(Map<String, String> p) {
        executeSqlTemplate("sql/get-owner-by-id-teardown.sql", p);
        executeSqlTemplate("sql/get-owner-by-id-setup.sql", p);
    }

    private String authenticate(Map<String, String> p) {
        return given().baseUri(BASE_URL)
                .contentType(ContentType.JSON)
                .body("\"{\\\"username\\\":\\\"admin\\\",\\\"password\\\":\\\"admin\\\"}\"")
        .when().post("/api/auth/login")
        .then().statusCode(200)
        .extract().jsonPath().getString("$.token");
    }

    @Test
    void NTC_getOwner_found(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", p.get("SEQ"))
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(200)
                    .body("firstName", equalTo("John"))
                    .body("lastName", equalTo("TestOwner"))
                    .body("address", equalTo("123 Main St"))
                    .body("city", equalTo("Madison"))
                    .body("telephone", equalTo("6085551234"));
            org.junit.jupiter.api.Assertions.assertEquals("1", queryScalar("SELECT COUNT(*) AS cnt FROM owners WHERE id = ?", p.get("SEQ")));
        } finally {
            executeSqlTemplate("sql/get-owner-by-id-teardown.sql", p);
        }
    }

    @Test
    void NTC_getOwner_verifyResponse(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", p.get("SEQ"))
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(200)
                    .body("firstName", notNullValue())
                    .body("lastName", notNullValue())
                    .body("address", containsString("Main"))
                    .body("telephone", notNullValue())
                    .body("pets", notNullValue());
            org.junit.jupiter.api.Assertions.assertEquals("1", queryScalar("SELECT COUNT(*) AS cnt FROM owners WHERE id = ?", p.get("SEQ")));
        } finally {
            executeSqlTemplate("sql/get-owner-by-id-teardown.sql", p);
        }
    }

    @Test
    void NTC_getOwner_allFields(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", p.get("SEQ"))
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(200)
                    .body("id", notNullValue())
                    .body("firstName", equalTo("John"))
                    .body("lastName", equalTo("TestOwner"))
                    .body("address", equalTo("123 Main St"))
                    .body("city", equalTo("Madison"))
                    .body("telephone", equalTo("6085551234"))
                    .body("pets", notNullValue());
            org.junit.jupiter.api.Assertions.assertEquals("1", queryScalar("SELECT COUNT(*) AS cnt FROM owners WHERE id = ?", p.get("SEQ")));
            org.junit.jupiter.api.Assertions.assertEquals("John", queryScalar("SELECT first_name FROM owners WHERE id = ?", p.get("SEQ")));
        } finally {
            executeSqlTemplate("sql/get-owner-by-id-teardown.sql", p);
        }
    }

    @Test
    void ATC_getOwner_notFound(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", "999999")
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(404);;
        } finally {
            executeSqlTemplate("sql/get-owner-by-id-teardown.sql", p);
        }
    }

    @Test
    void ATC_getOwner_invalidId(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", "abc")
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(400);;
        } finally {
            executeSqlTemplate("sql/get-owner-by-id-teardown.sql", p);
        }
    }
}

